INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','تكلفة انبوب الناقل 160 ملم للمزارع: دليل شامل للتقدير والميزانية' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','اطلع على دليل تقدير وتبويب ميزانية تكلفة انبوب الناقل 160 ملم في المزرعة لتخطيط ميزانيتك بدقة. يتضمن هذا الدليل معلومات تقنية حول الـ AFP وأفضل الممارسات للمزارعين العراقيين.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
