INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Learn essential maintenance practices for 75mm ribbed irrigation tubing to prevent damage and extend the operational lifespan of your drip irrigation systems. Technical best practices for farmers.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
