INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Бо раҳомотини мо, нигоҳубини ғамои шиназ 75 мм-ро омӯзед ва умри фойданоки онро дар системаҳои обёрӣи таматка зиёд кунед. Методҳои мубориза бо зарарҳо ва нигоҳубинии санҷидашуда.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
